SELECT * FROM orders WHERE id IN
#{id}
AND user_id = #{userId} AND is_deleted = 0

SELECT DISTINCT o.* FROM orders o
INNER JOIN order_items oi ON o.id = oi.order_id
INNER JOIN spu s ON oi.spu_id = s.id
WHERE s.seller_id = #{sellerId}

    AND o.status = #{status}


    AND o.user_id = #{userId}


    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND o.pay_time >= #{payTimeStart}


    AND o.pay_time <= #{payTimeEnd}


    AND o.delivery_time >= #{deliveryTimeStart}


    AND o.delivery_time <= #{deliveryTimeEnd}


    AND o.receive_time >= #{receiveTimeStart}


    AND o.receive_time <= #{receiveTimeEnd}

ORDER BY o.created_at DESC

SELECT COUNT(DISTINCT o.id) FROM orders o
INNER JOIN order_items oi ON o.id = oi.order_id
INNER JOIN spu s ON oi.spu_id = s.id
WHERE s.seller_id = #{sellerId}

    AND o.status = #{status}


    AND o.user_id = #{userId}


    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND o.pay_time >= #{payTimeStart}


    AND o.pay_time <= #{payTimeEnd}


    AND o.delivery_time >= #{deliveryTimeStart}


    AND o.delivery_time <= #{deliveryTimeEnd}


    AND o.receive_time >= #{receiveTimeStart}


    AND o.receive_time <= #{receiveTimeEnd}

SELECT * FROM orders
WHERE 1=1

    AND status = #{status}


    AND user_id = #{userId}


    AND order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND pay_time >= #{payTimeStart}


    AND pay_time <= #{payTimeEnd}


    AND delivery_time >= #{deliveryTimeStart}


    AND delivery_time <= #{deliveryTimeEnd}


    AND receive_time >= #{receiveTimeStart}


    AND receive_time <= #{receiveTimeEnd}

ORDER BY created_at DESC

SELECT COUNT(*) FROM orders
WHERE 1=1

    AND status = #{status}


    AND user_id = #{userId}


    AND order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND pay_time >= #{payTimeStart}


    AND pay_time <= #{payTimeEnd}


    AND delivery_time >= #{deliveryTimeStart}


    AND delivery_time <= #{deliveryTimeEnd}


    AND receive_time >= #{receiveTimeStart}


    AND receive_time <= #{receiveTimeEnd}
